#include <iostream>

namespace CGAL {
    enum Comparison_result { SMALLER, EQUAL, LARGER };
}

struct Point_2 {
    double _x, _y;
    Point_2(double x, double y) : _x(x), _y(y) {}
    double x() const { return _x; }
    double y() const { return _y; }
};

CGAL::Comparison_result compare_y(const Point_2& p, const Point_2& q) {
    if (p.y() < q.y()) return CGAL::SMALLER;
    if (p.y() > q.y()) return CGAL::LARGER;
    return CGAL::EQUAL;
}

int main() {
    Point_2 p1(0, 1), p2(0, 2), p3(0, 1);
    if (compare_y(p1, p2) == CGAL::SMALLER && 
        compare_y(p2, p1) == CGAL::LARGER && 
        compare_y(p1, p3) == CGAL::EQUAL) {
        std::cout << "Success" << std::endl;
        return 0;
    }
    return 1;
}

